/**
 * Guaranteed persisted-delta point probes using the unchanged primitive DELTA fixture. Every invocation visits its 32
 * known replacements or their tombstoned base quads once; scores are per lookup, not per 32-lookup invocation. Setup
 * independently verifies the actual delta keys and values in both directions, outside measurement.
 */
@State(Scope.Thread)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 2, time = 1)
@Measurement(iterations = 3, time = 1)
@Fork(value = 2, jvmArgsAppend = { "-Xms512m", "-Xmx512m" })
public class LmdbPersistentAdjacencyDeltaPointBenchmark {

	static final int POINTS = 32;
	private static final int PREDICATES = 8;

	@Param("4096")
	public int statementCount = 4096;
	@Param("false")
	public boolean incoming;

	LmdbPersistentAdjacencyBenchmark.Fixture fixture;
	long transaction;
	long[][] replacements;
	long[][] tombstones;

	@Setup(Level.Trial)
	public void setup() throws IOException {
		fixture = new LmdbPersistentAdjacencyBenchmark.Fixture(statementCount, "MIXED", PREDICATES, "DELTA", false);
		try {
			transaction = fixture.begin(true);
			replacements = new long[POINTS][];
			tombstones = new long[POINTS][];
			for (int point = 0; point < POINTS; point++) {
				int index = point * statementCount / POINTS;
				tombstones[point] = quad("MIXED", PREDICATES, index);
				replacements[point] = tombstones[point].clone();
				replacements[point][2] += REPLACEMENT_OFFSET;
				require(Arrays.equals(fixture.quads[index], replacements[point]), "known replacement index");
			}
			verifyDeltaRecords();
		} catch (IOException | RuntimeException | Error failure) {
			teardown();
			throw failure;
		}
	}

	/** Verifies storage directly, independently of the contains implementation being measured. */
	void verifyDeltaRecords() throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBStat stats = MDBStat.malloc(stack);
			E(mdb_stat(transaction, fixture.adjacency.deltasDbi(), stats));
			require(stats.ms_entries() == POINTS * 4L, "32 insertions and tombstones in both directions");
		}
		for (boolean direction : new boolean[] { false, true }) {
			for (int point = 0; point < POINTS; point++) {
				requireDelta(replacements[point], direction, 1);
				requireDelta(tombstones[point], direction, 0);
			}
		}
	}

	private void requireDelta(long[] point, boolean direction, int expected) throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			ByteBuffer key = stack.malloc(33).order(ByteOrder.BIG_ENDIAN);
			key.put(direction ? (byte) 1 : (byte) 0)
					.putLong(point[1])
					.putLong(point[direction ? 2 : 0])
					.putLong(point[direction ? 0 : 2])
					.putLong(point[3])
					.flip();
			MDBVal value = MDBVal.malloc(stack);
			E(mdb_get(transaction, fixture.adjacency.deltasDbi(), MDBVal.malloc(stack).mv_data(key), value));
			require(value.mv_size() == 1 && value.mv_data().get(0) == expected, "persisted point delta value");
		}
	}

	@Benchmark
	@OperationsPerInvocation(POINTS)
	public long deltaPresent() throws IOException {
		long found = 0;
		for (long[] point : replacements) {
			found += contains(fixture.adjacency, transaction, point, incoming) ? 1 : 0;
		}
		require(found == POINTS, "every replacement is present through a live delta");
		return found;
	}

	@Benchmark
	@OperationsPerInvocation(POINTS)
	public long deltaTombstone() throws IOException {
		long found = 0;
		for (long[] point : tombstones) {
			found += contains(fixture.adjacency, transaction, point, incoming) ? 1 : 0;
		}
		require(found == 0, "every old base quad is hidden by its tombstone");
		return found;
	}

	@TearDown(Level.Trial)
	public void teardown() {
		try {
			if (transaction != 0) {
				long closing = transaction;
				transaction = 0;
				mdb_txn_abort(closing);
			}
		} finally {
			if (fixture != null) {
				LmdbPersistentAdjacencyBenchmark.Fixture closing = fixture;
				fixture = null;
				closing.close();
			}
		}
	}
}
